#!/usr/bin/env node

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { loadWorkflow, workflowStep } from './workflow-source.cjs';

const metadataScript = workflowStep(loadWorkflow(), 'validate', 'id', 'metadata').run;

function runMetadata(changelog, version = '1.2.3', packageManifest = { name: 'fixture', version }) {
  const fixtureRoot = mkdtempSync(join(tmpdir(), 'release-notes-extraction-'));
  const runnerTemp = join(fixtureRoot, 'runner-temp');
  const githubOutput = join(fixtureRoot, 'github-output');
  mkdirSync(runnerTemp);
  writeFileSync(join(fixtureRoot, 'CHANGELOG.md'), changelog);
  writeFileSync(join(fixtureRoot, 'go.mod'), 'module example.test/fixture\n\ngo 1.24\n');
  writeFileSync(join(fixtureRoot, '.goreleaser.yml'), 'version: 2\n');
  writeFileSync(join(fixtureRoot, 'package.json'), JSON.stringify(packageManifest));

  let thrown;
  try {
    execFileSync('bash', ['-e', '-u', '-o', 'pipefail', '-c', metadataScript], {
      cwd: fixtureRoot,
      encoding: 'utf8',
      env: {
        ...process.env,
        ARCHIVE_FILES: '[]',
        EXTRA_PACKAGES: '[]',
        GITHUB_OUTPUT: githubOutput,
        GITHUB_RUN_ATTEMPT: '1',
        GITHUB_RUN_ID: '42',
        RELEASE_VERSION: version,
        RUNNER_TEMP: runnerTemp,
        SPLIT_GORELEASER_CONFIG: '',
      },
      stdio: 'pipe',
    });
  } catch (error) {
    thrown = error;
  }

  const notesPath = join(runnerTemp, 'RELEASE-NOTES.md');
  const result = {
    notes: thrown ? undefined : readFileSync(notesPath, 'utf8'),
    output: thrown ? undefined : readFileSync(githubOutput, 'utf8'),
    stderr: thrown?.stderr?.toString() ?? '',
    thrown,
  };
  rmSync(fixtureRoot, { recursive: true, force: true });
  return result;
}

const cases = [
  {
    name: 'version-first heading preserves exact section',
    changelog: '# Changelog\n\n## Unreleased\n\n- Future.\n\n## v1.2.3 - 2026-07-18\n\n- Exact café.\n\n## v1.2.2 - 2026-07-01\n\n- Older.\n',
    expected: '## v1.2.3 - 2026-07-18\n\n- Exact café.\n\n',
  },
  {
    name: 'date-first heading preserves exact section',
    changelog: '# Changelog\n\n## 2026-07-18 - [v1.2.3]\n\n- Date first.\n\n## 2026-07-01 - v1.2.2\n\n- Older.\n',
    expected: '## 2026-07-18 - [v1.2.3]\n\n- Date first.\n\n',
  },
  {
    name: 'fenced and commented headings remain section content',
    changelog: '# Changelog\n\n## v1.2.3 - 2026-07-18\n\n- Before examples.\n\n```md\n## example boundary\n## v1.2.3 - 2026-07-19\n```\n\n<!--\n## v1.2.3 - 2026-07-20\n-->\n\n- After examples.\n\n## v1.2.2 - 2026-07-01\n\n- Older.\n',
    expected: '## v1.2.3 - 2026-07-18\n\n- Before examples.\n\n```md\n## example boundary\n## v1.2.3 - 2026-07-19\n```\n\n<!--\n## v1.2.3 - 2026-07-20\n-->\n\n- After examples.\n\n',
  },
];

for (const fixture of cases) {
  const result = runMetadata(fixture.changelog);
  assert.equal(result.thrown, undefined);
  assert.equal(result.notes, fixture.expected);
  assert.equal(result.output, 'release-notes-artifact-name=release-notes-42-1\n');
  console.log(`PASS ${fixture.name}`);
}

const duplicate = runMetadata(
  '# Changelog\n\n## v1.2.3 - 2026-07-18\n\n- First.\n\n## 2026-07-19 - v1.2.3\n\n- Duplicate.\n',
);
assert.notEqual(duplicate.thrown, undefined);
assert.match(duplicate.stderr, /exactly one dated level-two section for 1\.2\.3; found 2/);
console.log('PASS duplicate dated version sections fail closed');

const versionlessRoot = runMetadata(
  '# Changelog\n\n## v1.2.3 - 2026-07-18\n\n- Versionless package fixture.\n',
  '1.2.3',
  { name: 'fixture', private: true },
);
assert.equal(versionlessRoot.thrown, undefined);
console.log('PASS versionless root package manifest is accepted');

console.log(`release notes extraction tests passed (${cases.length + 2} scenarios)`);

#!/usr/bin/env node
import assert from 'node:assert/strict';
import { loadWorkflow, workflowStep } from './workflow-source.cjs';

const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
const targetSha = 'a'.repeat(40);
const status = (state, context = 'external-ci') => ({ context, state });
const scenarios = [
  { name: 'failed status blocks a passing check', statuses: [status('failure')], failure: /external-ci=status\/failure/ },
  { name: 'errored status blocks a passing check', statuses: [status('error')], failure: /external-ci=status\/error/ },
  { name: 'pending status blocks a passing check', statuses: [status('pending')], failure: /external-ci=status\/pending/ },
  { name: 'new success supersedes old failure regardless of context case', statuses: [status('success', 'External-CI'), status('failure')] },
  { name: 'new failure supersedes old success', statuses: [status('failure'), status('success')], failure: /external-ci=status\/failure/ },
  { name: 'one failing context blocks other successful contexts', statuses: [status('success', 'lint'), status('failure')], failure: /external-ci=status\/failure/ },
  { name: 'successful statuses alone supply CI evidence', checks: false, statuses: [status('success')] },
  { name: 'no independent signal fails closed', checks: false, statuses: [], failure: /no independent CI/ },
  { name: 'status API failures fail closed', statuses: [], apiFailure: true, failure: /status service unavailable/ },
];

let failures = 0;
for (const archetype of ['swift-cli', 'electron']) {
  const script = workflowStep(loadWorkflow(`release-${archetype}.yml`), 'validate', 'name', 'Require independent CI green on frozen target').with.script;
  const execute = new AsyncFunction('github', 'context', 'core', 'process', script);
  for (const scenario of scenarios) {
    const errors = [];
    let statusReads = 0;
    const github = {
      rest: {
        actions: { listWorkflowRunsForRepo: 'runs' },
        checks: { listForRef: 'checks' },
        repos: { listCommitStatusesForRef: 'statuses' },
      },
      paginate: async (route, request) => {
        assert.deepEqual({ owner: request.owner, repo: request.repo }, { owner: 'openclaw', repo: 'fixture' });
        if (route === 'runs') {
          assert.equal(request.head_sha, targetSha);
          return [{ id: 101, event: 'push' }, { id: 102, event: 'schedule' }];
        }
        assert.equal(request.ref, targetSha, 'CI evidence must come from the frozen commit');
        if (route === 'checks') return [
          ...(scenario.checks === false ? [] : [{ name: 'build', status: 'completed', conclusion: 'success', details_url: 'https://github.com/openclaw/fixture/actions/runs/101/job/1' }]),
          { name: 'scheduled', status: 'completed', conclusion: 'failure', details_url: 'https://github.com/openclaw/fixture/actions/runs/102/job/2' },
        ];
        assert.equal(route, 'statuses');
        assert.equal(request.per_page, 100);
        statusReads += 1;
        if (scenario.apiFailure) throw new Error('status service unavailable');
        return scenario.statuses;
      },
    };
    try {
      await execute(github, { repo: { owner: 'openclaw', repo: 'fixture' }, runId: 42 }, {
        setFailed: (message) => errors.push(message),
      }, { env: { CI_CHECK_EVENTS: '["push"]', TARGET_SHA: targetSha } });
    } catch (error) {
      errors.push(error.message);
    }
    try {
      if (scenario.failure) assert.match(errors.join('\n'), scenario.failure);
      else assert.deepEqual(errors, []);
      assert.equal(statusReads, 1, 'commit statuses must be fetched even when event filtering is enabled');
      console.log(`PASS ${archetype}: ${scenario.name}`);
    } catch (error) {
      failures += 1;
      console.error(`FAIL ${archetype}: ${scenario.name}: ${error.message}`);
    }
  }
}
assert.equal(failures, 0);

#!/usr/bin/env node
import assert from 'node:assert/strict';
import { loadWorkflow, workflowStep } from './workflow-source.cjs';

const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
let failures = 0;
for (const archetype of ['go-cli', 'swift-cli', 'electron']) {
  const script = workflowStep(loadWorkflow(`release-${archetype}.yml`), 'validate', 'name', 'Require independent CI green on frozen target').with.script;
  const execute = new AsyncFunction('github', 'context', 'core', 'process', script);
  for (const prefixCollision of [false, true]) {
    const check = (id, conclusion) => ({ name: `check-${id}`, status: 'completed', conclusion, details_url: `https://github.com/openclaw/fixture/actions/runs/${id}/job/7` });
    const checks = [check(42, 'failure'), check(101, 'success')];
    if (prefixCollision) checks.push(check(421, 'failure'));
    const errors = [];
    const github = {
      rest: {
        actions: { listWorkflowRunsForRepo: 'runs' },
        checks: { listForRef: 'checks' },
        repos: { listCommitStatusesForRef: 'statuses', getBranch: async () => ({ data: {} }) },
      },
      paginate: async (route) => {
        if (route === 'checks') return checks;
        if (route === 'runs') return [42, 101, 421].map((id) => ({ id, event: 'push' }));
        if (route === 'statuses' || route.includes('/rules/branches/')) return [];
        throw new Error(`unexpected API route ${route}`);
      },
    };
    await execute(github, { repo: { owner: 'openclaw', repo: 'fixture' }, runId: 42 }, {
      info() {}, warning() {}, setFailed: (message) => errors.push(message),
    }, { env: { CI_CHECK_EVENTS: '["push"]', DEFAULT_BRANCH: 'main', STRICT_CHECKS: 'false', TARGET_SHA: 'a'.repeat(40) } });
    try {
      assert.equal(errors.length > 0, prefixCollision, 'only the exact current run may be excluded');
      if (prefixCollision) assert.match(errors[0], /check-421=completed\/failure/);
      console.log(`PASS ${archetype}: ${prefixCollision ? 'independent prefix run blocks release' : 'exact current run excluded'}`);
    } catch (error) {
      failures += 1;
      console.error(`FAIL ${archetype}: ${error.message}`);
    }
  }
}
assert.equal(failures, 0);

#!/usr/bin/env node

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { chmodSync, mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { extractMarkedSource, loadWorkflow, workflowStep } from './workflow-source.cjs';

const require = createRequire(import.meta.url);
const script = workflowStep(loadWorkflow(), 'compare', 'name', 'Require byte-identical independent rebuild').run;
const verify = new Function('require', 'process',
  extractMarkedSource(script, '// reproducible-rebuild-verifier-begin', '// reproducible-rebuild-verifier-end'));

const targets = [
  ['linux', 'amd64', 'fixture'],
  ['linux', 'arm64', 'fixture'],
  ['windows', 'amd64', 'fixture.exe'],
  ['windows', 'arm64', 'fixture.exe'],
];

const fixture = () => {
  const root = mkdtempSync(join(tmpdir(), 'release-reproducible-rebuild-'));
  const source = join(root, 'reproducible-source');
  const release = join(root, 'release-assets');
  mkdirSync(join(source, 'dist'), { recursive: true });
  mkdirSync(release);
  const artifacts = [];
  const binaryRows = [];
  const targetRows = [];
  for (const [goos, goarch, binary] of targets) {
    const target = `${goos}_${goarch}`;
    const binaryPath = join(source, 'dist', `fixture_${target}`, binary);
    mkdirSync(dirname(binaryPath), { recursive: true });
    writeFileSync(binaryPath, `reproducible:${target}\n`);
    chmodSync(binaryPath, 0o755);
    artifacts.push({ type: 'Binary', name: binary, path: `dist/fixture_${target}/${binary}`, goos, goarch });
    const archiveName = `fixture_1.2.3_${target}.${goos === 'windows' ? 'zip' : 'tar.gz'}`;
    const staging = join(root, `staging-${target}`);
    mkdirSync(staging);
    writeFileSync(join(staging, binary), `reproducible:${target}\n`);
    if (goos === 'windows') {
      execFileSync('zip', ['-q', join(release, archiveName), binary], { cwd: staging });
    } else {
      execFileSync('tar', ['-czf', join(release, archiveName), binary], { cwd: staging });
    }
    targetRows.push({ name: archiveName, target });
    binaryRows.push({ target, archive: archiveName, member: binary });
  }
  writeFileSync(join(source, 'dist', 'artifacts.json'), `${JSON.stringify(artifacts)}\n`);
  writeFileSync(join(release, '.ASSET-TARGETS.json'), `${JSON.stringify(targetRows)}\n`);
  writeFileSync(join(release, '.ASSET-BINARIES.json'), `${JSON.stringify(binaryRows)}\n`);
  return { root, source };
};

const run = (mutate = () => {}) => {
  const test = fixture();
  const previousCwd = process.cwd();
  const previous = new Map();
  const environment = {
    GITHUB_REPOSITORY: 'openclaw/fixture',
    GO_VERSION: 'go1.26.5',
    GORELEASER_VERSION: '2.17.1',
    REPRODUCIBLE_REBUILD: 'non-darwin',
    REPRODUCIBLE_REBUILD_PROOF: join(test.root, 'proof.json'),
    TAG: 'v1.2.3',
    TARGET_SHA: 'a'.repeat(40),
  };
  try {
    mutate(test);
    for (const [key, value] of Object.entries(environment)) {
      previous.set(key, process.env[key]);
      process.env[key] = value;
    }
    process.chdir(test.root);
    verify(require, process);
    return JSON.parse(readFileSync(environment.REPRODUCIBLE_REBUILD_PROOF, 'utf8'));
  } finally {
    process.chdir(previousCwd);
    for (const [key, value] of previous) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    rmSync(test.root, { recursive: true, force: true });
  }
};

const proof = run();
assert.equal(proof.mode, 'non-darwin');
assert.deepEqual(proof.targets.map((row) => row.target), [
  'linux_amd64', 'linux_arm64', 'windows_amd64', 'windows_arm64',
]);
assert.ok(proof.targets.every((row) => row.stagedSha256 === row.rebuiltSha256));
console.log('PASS all four non-Darwin staged binaries match an independent rebuild');

assert.throws(() => run(({ source }) => {
  writeFileSync(join(source, 'dist', 'fixture_linux_amd64', 'fixture'), 'different bytes\n');
}), /reproducible rebuild mismatch for linux_amd64/);
console.log('PASS a single-byte-independent mismatch fails closed');

assert.throws(() => run(({ root }) => {
  const manifest = join(root, 'release-assets', '.ASSET-BINARIES.json');
  const rows = JSON.parse(readFileSync(manifest, 'utf8'));
  rows.push({
    target: 'linux_amd64',
    archive: 'fixture_1.2.3_linux_amd64.tar.gz',
    member: 'extra',
  });
  writeFileSync(manifest, `${JSON.stringify(rows)}\n`);
}), /binary set differs/);
console.log('PASS an omitted staged binary fails exact-set comparison');

const aliasProof = run(({ source }) => {
  const manifest = join(source, 'dist', 'artifacts.json');
  const artifacts = JSON.parse(readFileSync(manifest, 'utf8'));
  artifacts.push({ ...artifacts.find((artifact) => artifact.path === 'dist/fixture_linux_amd64/fixture') });
  writeFileSync(manifest, `${JSON.stringify(artifacts)}\n`);
});
assert.equal(aliasProof.targets.length, 4);
console.log('PASS duplicate GoReleaser aliases for one physical binary are deduplicated');

assert.throws(() => run(({ root }) => {
  const archive = join(root, 'release-assets', 'fixture_1.2.3_linux_amd64.tar.gz');
  const staging = join(root, 'unsafe-staging');
  mkdirSync(staging);
  writeFileSync(join(staging, 'fixture'), 'reproducible:linux_amd64\n');
  writeFileSync(join(staging, '--checkpoint-action=echo'), 'unsafe\n');
  execFileSync('tar', ['-czf', archive, '--', 'fixture', '--checkpoint-action=echo'], { cwd: staging });
}), /unsafe archive member/);
console.log('PASS option-like archive members fail before extraction');

assert.throws(() => run(({ root }) => {
  const manifest = join(root, 'release-assets', '.ASSET-BINARIES.json');
  const rows = JSON.parse(readFileSync(manifest, 'utf8'));
  rows.find((row) => row.target === 'windows_amd64').member = 'fixture*.exe';
  writeFileSync(manifest, `${JSON.stringify(rows)}\n`);
}), /staged binary manifest contains an invalid row/);
console.log('PASS ZIP wildcard member names are rejected before extraction');

console.log('reproducible rebuild tests passed (6 scenarios)');

#!/usr/bin/env node

import assert from 'node:assert/strict';
import { extractMarkedSource, loadWorkflow, workflowStep } from './workflow-source.cjs';

const script = workflowStep(loadWorkflow(), 'validate', 'name', 'Require independent CI green on frozen target').with.script;
const source = `${extractMarkedSource(script, '// ci-check-event-filter-begin', '// ci-check-event-filter-end')}
return filterCheckRunsByEvent;`;
const loadFilter = new Function(source);
const filterCheckRunsByEvent = loadFilter();
const gateSource = `${extractMarkedSource(script, '// ci-check-gate-helpers-begin', '// ci-check-gate-helpers-end')}
return { evaluateAllChecks, evaluateRequiredChecks, evaluateCiGate, waitForCiGate };`;
const loadGateHelpers = new Function(gateSource);
const { evaluateAllChecks, evaluateRequiredChecks, evaluateCiGate, waitForCiGate } = loadGateHelpers();

const actionsCheck = (name, runId) => ({
  name,
  details_url: `https://github.com/openclaw/fixture/actions/runs/${runId}/job/${runId + 1000}`,
});
const unresolvedCheck = { name: 'CodeQL', details_url: 'https://github.com/openclaw/fixture/runs/99' };

function runFilter(allowedEvents, workflowRunEvents = new Map([[1, 'push'], [2, 'schedule']])) {
  const info = [];
  const accepted = filterCheckRunsByEvent({
    checkRuns: [
      actionsCheck('ci', 1),
      actionsCheck('ci companion', 1),
      actionsCheck('publish', 2),
      actionsCheck('unresolved Actions check', 3),
      unresolvedCheck,
      { name: 'current release', details_url: 'https://github.com/openclaw/fixture/actions/runs/42/job/7' },
    ],
    allowedEvents: new Set(allowedEvents),
    currentRunId: 42,
    workflowRunEvents,
    info: (message) => info.push(message),
  });
  return { accepted, info };
}

const unfiltered = runFilter([]);
assert.deepEqual(unfiltered.accepted.map((check) => check.name), [
  'ci', 'ci companion', 'publish', 'unresolved Actions check', 'CodeQL',
]);

const pushOnly = runFilter(['push', 'pull_request']);
assert.deepEqual(pushOnly.accepted.map((check) => check.name), [
  'ci', 'ci companion', 'unresolved Actions check', 'CodeQL',
]);
assert.deepEqual(pushOnly.info, ['Ignoring publish from Actions event schedule']);

const failedResolution = runFilter(['push'], new Map());
assert.equal(failedResolution.accepted.length, 5);

const acceptableConclusions = new Set(['success', 'neutral', 'skipped']);
const check = (name, status, conclusion = null, appId = 1) => ({
  name,
  status,
  conclusion,
  app: { id: appId },
});
const status = (context, state, login = 'github-actions[bot]') => ({
  context,
  state,
  creator: { login, type: 'Bot' },
});
const latestStatuses = (statuses) =>
  new Map(statuses.map((candidate) => [candidate.context.toLowerCase(), candidate]));

const wacrawlPending = evaluateAllChecks({
  checkRuns: [
    check('deps', 'completed', 'success'),
    check('release-check', 'in_progress'),
    check('secrets', 'completed', 'success'),
    check('lint', 'in_progress'),
    check('test', 'in_progress'),
  ],
  latestStatuses: new Map(),
  acceptableConclusions,
});
assert.equal(wacrawlPending.state, 'pending');
assert.deepEqual(wacrawlPending.observed, [
  'release-check=in_progress/null',
  'lint=in_progress/null',
  'test=in_progress/null',
]);

const wacrawlGreen = evaluateAllChecks({
  checkRuns: [
    check('deps', 'completed', 'success'),
    check('release-check', 'completed', 'success'),
    check('secrets', 'completed', 'success'),
    check('lint', 'completed', 'success'),
    check('test', 'completed', 'success'),
  ],
  latestStatuses: new Map(),
  acceptableConclusions,
});
assert.equal(wacrawlGreen.state, 'success');

const completedFailure = evaluateAllChecks({
  checkRuns: [check('test', 'completed', 'failure')],
  latestStatuses: new Map(),
  acceptableConclusions,
});
assert.equal(completedFailure.state, 'failure');
assert.deepEqual(completedFailure.observed, ['test=completed/failure']);

const noSignal = evaluateAllChecks({
  checkRuns: [],
  latestStatuses: new Map(),
  acceptableConclusions,
});
assert.equal(noSignal.state, 'pending');
assert.deepEqual(noSignal.observed, ['no independent CI check or commit status']);

const pendingStatus = evaluateAllChecks({
  checkRuns: [],
  latestStatuses: latestStatuses([status('legacy-ci', 'pending')]),
  acceptableConclusions,
});
assert.equal(pendingStatus.state, 'pending');
assert.deepEqual(pendingStatus.observed, ['legacy-ci=status/pending']);

const required = new Map([
  ['lint\u0000*', { name: 'lint', normalizedName: 'lint', appId: null }],
  ['test\u00001', { name: 'test', normalizedName: 'test', appId: 1 }],
]);
const requiredPending = await evaluateRequiredChecks({
  required,
  checkRuns: [check('lint', 'completed', 'success')],
  allStatuses: [],
  latestStatuses: new Map(),
  acceptableConclusions,
  normalizeContext: (name) => name.toLowerCase(),
  statusAppId: async () => null,
});
assert.equal(requiredPending.state, 'pending');
assert.deepEqual(requiredPending.observed, ['test@app:1=missing']);

const requiredFailure = await evaluateRequiredChecks({
  required,
  checkRuns: [
    check('lint', 'completed', 'success'),
    check('test', 'completed', 'failure'),
  ],
  allStatuses: [],
  latestStatuses: new Map(),
  acceptableConclusions,
  normalizeContext: (name) => name.toLowerCase(),
  statusAppId: async () => null,
});
assert.equal(requiredFailure.state, 'failure');
assert.deepEqual(requiredFailure.observed, ['test@app:1=completed/failure']);

const requiredGreen = await evaluateRequiredChecks({
  required,
  checkRuns: [
    check('lint', 'completed', 'success'),
    check('test', 'completed', 'success'),
  ],
  allStatuses: [],
  latestStatuses: new Map(),
  acceptableConclusions,
  normalizeContext: (name) => name.toLowerCase(),
  statusAppId: async () => null,
});
assert.equal(requiredGreen.state, 'success');

const optionalPending = check('optional', 'in_progress');
const defaultRequiredGate = await evaluateCiGate({
  required,
  strictChecks: false,
  checkRuns: [
    check('lint', 'completed', 'success'),
    check('test', 'completed', 'success'),
    optionalPending,
  ],
  allStatuses: [],
  latestStatuses: new Map(),
  acceptableConclusions,
  normalizeContext: (name) => name.toLowerCase(),
  statusAppId: async () => null,
});
assert.equal(defaultRequiredGate.state, 'success');
assert.equal(defaultRequiredGate.mode, 'required');

const strictRequiredGate = await evaluateCiGate({
  required,
  strictChecks: true,
  checkRuns: [
    check('lint', 'completed', 'success'),
    check('test', 'completed', 'success'),
    optionalPending,
  ],
  allStatuses: [],
  latestStatuses: new Map(),
  acceptableConclusions,
  normalizeContext: (name) => name.toLowerCase(),
  statusAppId: async () => null,
});
assert.equal(strictRequiredGate.state, 'pending');
assert.equal(strictRequiredGate.mode, 'all');
assert.deepEqual(strictRequiredGate.observed, ['optional=in_progress/null']);

const strictTerminalFailure = await evaluateCiGate({
  required,
  strictChecks: true,
  checkRuns: [
    check('lint', 'completed', 'success'),
    check('test', 'in_progress'),
    check('optional', 'completed', 'failure'),
  ],
  allStatuses: [],
  latestStatuses: new Map(),
  acceptableConclusions,
  normalizeContext: (name) => name.toLowerCase(),
  statusAppId: async () => null,
});
assert.equal(strictTerminalFailure.state, 'failure');
assert.equal(strictTerminalFailure.mode, 'all');
assert.deepEqual(strictTerminalFailure.observed, ['optional=completed/failure']);

const wrongAppPending = status('test', 'pending', 'wrong-app[bot]');
const correctAppPending = status('test', 'pending', 'correct-app[bot]');
